// Vse simulacije pri temi kot seznam { id, title, opts }.
export function simsForTopic(topicId) {
  const v = SIM_TOPICS[topicId];
  if (!v) return [];
  const list = Array.isArray(v[0]) ? v : [v];
  return list.map(([id, title, opts]) => ({ id, title, opts: opts || {} }));
}
